def _check_python_syntax_impl(code: str) -> str:
    import ast

    try:
        ast.parse(code)
    except SyntaxError as exc:
        return f"SyntaxError: {exc.msg} (line {exc.lineno})"
    return "OK"


def check_python_syntax(code: str) -> str:
    """Check whether a Python source string parses. Returns 'OK', or the SyntaxError message with its line number."""
    return _check_python_syntax_impl(code)
